#include <cstdio>

int main() {
    long long a, b, c, d;
    if (scanf("%lld %lld %lld %lld", &a, &b, &c, &d) != 4) return 0;
    // Walk backwards: the predecessor of (c,d) is forced by which coordinate is larger.
    bool ok = true;
    while (!(c == a && d == b)) {
        if (c < a || d < b || c == d) { ok = false; break; }
        if (c > d) c -= d; else d -= c;
    }
    puts(ok ? "Yes" : "No");
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong(), b = sc.nextLong(), c = sc.nextLong(), d = sc.nextLong();
        // Walk backwards: the predecessor of (c,d) is forced by which coordinate is larger.
        boolean ok = true;
        while (!(c == a && d == b)) {
            if (c < a || d < b || c == d) { ok = false; break; }
            if (c > d) c -= d; else d -= c;
        }
        System.out.println(ok ? "Yes" : "No");
    }
}

package main

import "fmt"

func main() {
	var a, b, c, d int64
	fmt.Scan(&a, &b, &c, &d)
	// Walk backwards: the predecessor of (c,d) is forced by which coordinate is larger.
	ok := true
	for !(c == a && d == b) {
		if c < a || d < b || c == d {
			ok = false
			break
		}
		if c > d {
			c -= d
		} else {
			d -= c
		}
	}
	if ok {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}
